namespace Xdb.Api.Infrastructure.Data.Entities.Common;

/// <summary>
/// Base for every entity whose primary key is a single column named <c>Id</c>.
/// The original schema uses <see cref="System.Guid"/> for most tables, <c>int</c> for logs and caches,
/// and <c>byte</c> for a few system lookups. Keys are generated by database defaults (<c>newid()</c>, identity).
/// </summary>
public abstract class EntityBase<TKey>
    where TKey : struct
{
    public TKey Id { get; set; }
}
